SourceCode.Declaration:
/// <summary>
/// Extension class for InventDim to handle fixed batch number
/// </summary>
[ExtensionOf(tableStr(InventDim))]
internal final class AVA_InventDim_Extension
{
}

Method.Source:
/// <summary>
/// Gets the fixed batch number if configured for the item's tracking number group
/// </summary>
/// <param name="_itemId">Item ID</param>
/// <returns>Fixed batch number or empty string</returns>
public static InventBatchId AVA_getFixedBatchNumber(ItemId _itemId)
{
    InventBatchId batchId = '';
    InventTable inventTable;
    InventNumGroup inventNumGroup;

    select firstonly NumGroupId from inventTable
        where inventTable.ItemId == _itemId
        join AVA_FixedBatch, AVA_FixedBatchNumber from inventNumGroup
            where inventNumGroup.NumberSeqGroupId == inventTable.NumGroupId
                && inventNumGroup.AVA_FixedBatch == NoYes::Yes;

    if (inventNumGroup.AVA_FixedBatchNumber)
    {
        batchId = inventNumGroup.AVA_FixedBatchNumber;
    }

    return batchId;
}
